function renderLevelUp(report){const panel=$('levelUpPanel');if(!panel)return;panel.innerHTML='';panel.classList.toggle('hidden',!report);if(report&&window.LevelUpFX)try{window.LevelUpFX.render(panel,report,{icon,tone,typeName:t=>F.TYPE[t]?.[0]||t,openSkills:()=>{$('resultContinue').click();setTimeout(()=>skills.open('pokemon'),60)}})}catch{panel.classList.add('hidden')}}
function endBattle(){C.persistHealth(battle);F.resolveLegendBattle(state,battle);const tutorial=battle?.encounter.tutorial;const completion=state.generationJourney.notice;const lost=battle?.result==='loss';if(battle?.encounter.kind==='trainer')ignoredTrainers.add(battle.encounter.key);trainerAlert=null;trainerGrace=2;wildGrace=1.5;grassStep=-4;battle=null;if(F.MAPS[state.mapId].kind==='gym')resetCaches();if(lost){F.moveToMap(state,state.lastTown,null);resetCaches()}finished=false;paused=false;$('arenaMessage').classList.add('hidden');$('resultDialog').close();clearInput();setMode();renderUI();save();if(tutorial){F.healTeam(state);save();renderUI();showOpening();return}if(completion){state.generationJourney.notice=null;save();showGenerationComplete(completion);}canvas.focus({preventScroll:true})}
function updateBattle(dt){C.step(battle,dt,keys);renderKeyboardHUD();if(C.moves(battle.fighters[0]).map(m=>m.key).join()!==moveSignature){renderMoves();void loadSpecies(C.moveCreature(battle.fighters[0]).id,true)}const [p,e]=battle.fighters;if(battle.encounter.tutorial){const t=battle.tutorial;$('tutorialGuide').textContent=!t.moved?'Ciprés · 1/5: mueve a tu Pokémon con el mando o WASD / flechas.':!t.attacked?'Ciprés · 2/5: acércate y usa una técnica con daño (botón o tecla 1).':!t.dodged?'Ciprés · 3/5: pulsa Esquiva o Espacio. Consume stamina y evita golpes.':!t.rested?'Ciprés · 4/5: suelta el mando unos segundos. Al moverte, la energía no se recupera y la stamina regenera a la mitad.':'Ciprés · 5/5: vence al Pokémon de Ivo. Acércate para golpear y haz pausas para recuperar recursos.';$('tutorialGuide').classList.toggle('hidden',!!battle.result);}$('enemyName').textContent=F.DATA[C.moveCreature(e).id].name;$('enemyLevel').textContent='Nv. '+e.creature.level+(battle.enemyRoster.length>1?' · '+(battle.enemyIndex+1)+' / '+battle.enemyRoster.length:'');for(const [side,a] of [['player',p],['enemy',e]]){const cap=C.staminaCap(a);$(side+'HP').style.width=a.hp/a.maxHP*100+'%';$(side+'Energy').style.width=a.energy+'%';$(side+'EnergyText').textContent=Math.round(a.energy);$(side+'EnergyText').title=a.moving?'En movimiento: energía sin regeneración':'En reposo: recuperación de energía';$(side+'Stamina').style.width=a.stamina+'%';$(side+'StaminaText').textContent=Math.floor(a.stamina)+' / '+Math.round(cap);$(side+'StaminaText').title=a.moving?'En movimiento: regeneración de stamina al 50 %':'En reposo: regeneración de stamina completa';$(side+'StaminaCap').style.left=cap+'%';$(side+'Status').innerHTML=Object.entries(a.statuses).map(([key,value])=>`<span style="border-color:${C.STATUS[key][1]}">${C.STATUS[key][0]} ${Math.ceil(value.time)}s</span>`).join('')}
const ball=F.ITEMS[$('ballSelect').value];$('captureBtn').disabled=!!battle.result||['gym','trainer'].includes(battle.encounter.kind)||!ball||F.itemCount(state,ball.key)<1||(ball.key!=='master-ball'&&e.hp/e.maxHP>(battle.encounter.captureLimit||.35))||p.cd.capture>0||battle.intro>0||battle.awaitingSwitch;$('captureBtn').textContent=['gym','trainer'].includes(battle.encounter.kind)?'Pokémon de entrenador':'Capturar · C';const escape=C.canEscape(battle);$('fleeBtn').disabled=paused||isModal()||!escape.ready;$('fleeBtn').textContent=battle.escapeCooldown>0?'Escapar · '+battle.escapeCooldown.toFixed(1)+' s':escape.needsWeakening?escape.reason:'Intentar escapar · R';$('fleeBtn').title=escape.ready?'R · '+Math.round(escape.chance*100)+' % de éxito. Alejarte del rival y tu velocidad ayudan.':'R · '+escape.reason;const hasMedicine=['sitrus-berry','oran-berry','potion','super-potion','hyper-potion','max-potion','full-restore','lum-berry','full-heal','leppa-berry','ether'].some(k=>F.itemCount(state,k)>0);$('healBtn').textContent='Curar · B';$('healBtn').disabled=!!battle.result||!hasMedicine||p.cd.berry>0||(p.hp>=p.maxHP&&p.energy>=100&&Object.keys(p.statuses).length===0)||battle.intro>0||battle.awaitingSwitch;
C.moves(p).forEach(m=>{const i=m.slot,key='m'+i,cd=p.cd[key],use=C.canUse(battle,0,key);$('cooldown'+i).style.width=cd/m.cooldown*100+'%';$('move'+i).classList.toggle('waiting',!use.ready);$('move'+i).classList.toggle('ready',use.ready);$('moveText'+i).textContent=cd>0?'Recarga · '+cd.toFixed(1)+' s':use.ready?m.description:use.reason;$('move'+i).disabled=!use.ready});$('dodgeBtn').disabled=!C.canUse(battle,0,'dash').ready;$('battleTeamBtn').disabled=!!battle.result||battle.roster.filter(a=>a.hp>0).length<2||battle.switchCooldown>0;$('battleTeamBtn').title=battle.switchCooldown>0?'Cambio en '+battle.switchCooldown.toFixed(1)+' s':'Cambiar Pokémon · Q';if(battle.awaitingSwitch&&!isModal())showTeam();if(battle.ending?.elapsed>=battle.ending?.duration)finishBattle()}
function tileArt(x,y,t,tx,ty,c){c=c||ctx;if(t.gym){GymArt.tile(c,x,y,t,tx,ty,time);return}if(t.ground==='waterfall'){FieldArt.waterfall(c,x,y,time);return}if(TerrainArt.ground(c,x,y,t,tx,ty,time))return;if(t.ground==='wall'){c.fillStyle='#34483d';c.fillRect(x,y,32,32);c.fillStyle='#26392f';c.fillRect(x+1,y+1,29,12);c.fillRect(x+4,y+18,20,9);return}if(t.ground==='dungeon'){c.fillStyle='#6a7b6b';c.fillRect(x,y,32,32);c.fillStyle='#7c8d7a';c.fillRect(x+2,y+2,27,13);c.fillRect(x+4,y+18,23,12);return}if(t.ground==='trail'){c.fillStyle='#c3bc94';c.fillRect(x,y,32,32);c.fillStyle='#d5c9a4';c.fillRect(x+6,y+9,10,2);c.fillRect(x+20,y+24,5,2);return}if(t.ground==='paved'){c.fillStyle='#bfc0a7';c.fillRect(x,y,32,32);c.fillStyle='#a6ad96';c.fillRect(x,y+31,32,1);c.fillRect(x+((ty%2)*16),y,1,32);c.fillStyle='#d0d0b9';c.fillRect(x+3,y+3,10,1);return}const palette=t.ground==='water'?(t.biome==='pantano'?['#697f75','#8c9c7c']:['#639eab','#83b9bb']):t.ground==='sand'?['#cfb97e','#dcc98f']:t.ground==='snow'?['#cdd9d4','#dfe5dc']:t.ground==='rock'?(t.biome==='volcán'?['#78685d','#94816c']:['#98a49a','#abb4a5']):t.biome==='selva'?['#537e59','#6d985e']:t.biome==='pantano'?['#727f59','#889369']:t.biome==='bosque'?['#749568','#83a573']:['#97b57c','#a8c188'];c.fillStyle=palette[0];c.fillRect(x,y,32,32);c.fillStyle=palette[1];let h=F.hash(tx,ty,state.seed);if(t.ground==='water'){let offset=Math.floor(time*2+tx+ty)%3;c.fillRect(x+4+offset*3,y+10,12,2);c.fillRect(x+18-offset*2,y+23,8,2)}else{for(let i=0;i<3;i++){let px=Math.floor(F.hash(tx+i*11,ty,state.seed)*26),py=Math.floor(F.hash(tx,ty+i*13,state.seed)*26);c.fillRect(x+px,y+py,t.ground==='sand'?3:2,2)}if(h>.86&&t.ground==='grass'){c.fillStyle=h>.94?'#e0d27b':'#e8ebbb';c.fillRect(x+12,y+18,3,3);c.fillRect(x+11,y+17,2,2)}}}

function updateFollow(dt){const p=state.player;
 if(!follow||followMap!==state.mapId||Math.hypot(follow.x-p.x,follow.y-p.y)>240){followMap=state.mapId;followTrail=[{x:p.x,y:p.y}];follow={x:p.x-25,y:p.y+18,moving:false,idle:0}}
 const last=followTrail[followTrail.length-1];if(Math.hypot(p.x-last.x,p.y-last.y)>=4){followTrail.push({x:p.x,y:p.y});if(followTrail.length>48)followTrail.shift()}
 follow.idle=trainerMoving?0:follow.idle+dt;
 // moving: trail the path just walked; standing: settle beside the trainer on any free spot
 let tx=p.x-25,ty=p.y+18;
 if(follow.idle>.3||followTrail.length<2){
  const free=(x,y)=>!cachedTile(Math.floor(x/32),Math.floor(y/32)).block&&!F.mapBlocked(state.mapId,x,y);
  const c=[[-25,18],[25,18],[0,26],[-26,-2],[26,-2]].map(o=>[p.x+o[0],p.y+o[1]]).find(o=>free(o[0],o[1]));
  if(c){tx=c[0];ty=c[1]}else{tx=p.x;ty=p.y+10}
 }else{
  let acc=0,prev={x:p.x,y:p.y};
  for(let i=followTrail.length-1;i>=0;i--){const q=followTrail[i],seg=Math.hypot(prev.x-q.x,prev.y-q.y);if(acc+seg>=34){const k=(34-acc)/(seg||1);tx=prev.x+(q.x-prev.x)*k;ty=prev.y+(q.y-prev.y)*k+8;break}acc+=seg;prev=q}
 }
 const dx=tx-follow.x,dy=ty-follow.y,k=Math.min(1,dt*9);follow.x+=dx*k;follow.y+=dy*k;follow.moving=Math.hypot(dx,dy)>3||trainerMoving}
function trainer(x,y,dir,moving){const gt=state.field.surfing?null:cachedTile(Math.floor(state.player.x/32),Math.floor(state.player.y/32));TrainerArt.draw(ctx,x,y,dir,walkDistance,moving,time,reducedMotion,state.avatar,gt?gt.ground:'',trainerRunning)}
function spriteExtent(id){return window.SpriteArt.extent(id)}
function drawTallFront(camera){if(!window.TerrainArt?.tall||F.MAPS[state.mapId].kind==='cave')return;const sway=reducedMotion?0:trainerMoving?2:1,spots=[{x:state.player.x,y:state.player.y,w:15,up:9}];if(follow&&followMap===state.mapId&&!state.field.surfing)spots.push({x:follow.x,y:follow.y,w:12,up:6});for(const s of spots){const tx=Math.floor(s.x/32),ty=Math.floor(s.y/32);if(!cachedTile(tx,ty).tall)continue;const sx=s.x-camera.x,sy=s.y-camera.y;ctx.save();ctx.beginPath();ctx.rect(sx-s.w,sy-s.up,s.w*2,s.up+3);ctx.clip();for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++){const t=cachedTile(tx+i,ty+j);if(t.tall)TerrainArt.tall(ctx,Math.floor((tx+i)*32-camera.x),Math.floor((ty+j)*32-camera.y),t,time,true,sway)}ctx.restore()}}
function drawWorld(){const camera={x:state.player.x-W/2,y:state.player.y-H/2},x0=Math.floor(camera.x/32),y0=Math.floor(camera.y/32),actors=[];ctx.clearRect(0,0,W,H);const fx=window.WorldFX;if(fx){const mp=F.MAPS[state.mapId];fx.begin({getTile:cachedTile,time,reduced:reducedMotion,kind:mp.kind,base:F.districtBase?.(mp.region)||mp.region,seed:state.seed,mapId:state.mapId})}const chunked=fx?fx.ground(ctx,camera,x0,y0,(g,px,py,pt,tx,ty)=>{tileArt(px,py,pt,tx,ty,g);fx.staticTile(g,px,py,pt,tx,ty);TerrainArt.details(g,px,py,pt)}):false;for(let y=y0-1;y<y0+19;y++)for(let x=x0-1;x<x0+32;x++){const t=cachedTile(x,y),sx=Math.floor(x*32-camera.x),sy=Math.floor(y*32-camera.y);if(chunked&&fx.isStatic(t))fx.animTile(ctx,sx,sy,t,x,y);else{tileArt(sx,sy,t,x,y);if(fx)fx.tile(ctx,sx,sy,t,x,y);TerrainArt.details(ctx,sx,sy,t)}if(t.obstacle&&!t.gym&&t.obstacle!=='cliff')actors.push({kind:'obstacle',x:sx+16,y:sy+32,t})}
if(F.MAPS[state.mapId].kind==='town'&&!F.townPlan?.(state.mapId))for(const [x,y] of [[-176,-440],[176,-440],[-368,48],[368,160],[-112,512],[256,512]])WorldArt.park(ctx,x-camera.x,y-camera.y);
if(F.MAPS[state.mapId].kind!=='town')for(const p of F.mapLayout(state.mapId,state.seed).landmarks)actors.push({kind:'landmark',x:p.x-camera.x,y:p.y-camera.y,p});
const town=F.mapTown(state.mapId),{wild,loot}=visibleObjects();for(const o of F.cardObjects(state))WorldArt.card(ctx,o.x-camera.x,o.y-camera.y,o.color,time);for(const p of F.legendObjects(state))actors.push({kind:'legend',x:p.x-camera.x,y:p.y-camera.y,p});for(const l of loot){const x=l.x-camera.x,y=l.y-camera.y;if(x<-40||x>W+40||y<-40||y>H+40)continue;WorldArt.pokeball(ctx,x,y)}
for(const w of wild){const x=w.x-camera.x,y=w.y-camera.y;if(x>-40&&x<W+40&&y>-40&&y<H+40)WorldArt.trace(ctx,w,x,y,near?.kind==='wild'&&near.key===w.key,time,Math.hypot(w.x-state.player.x,w.y-state.player.y))}
town?.buildings.forEach(b=>actors.push({kind:'building',x:b.x-camera.x,y:b.y+b.h-camera.y,b}));if(town)actors.push({kind:'fountain',x:(town.fountain?town.fountain.x:0)-camera.x,y:(town.fountain?town.fountain.y:-16)-camera.y});[...(town?.points||[]),...F.mapPeople(state)].forEach(p=>actors.push({kind:'npc',x:p.x-camera.x,y:p.y-camera.y,p}));actors.push({kind:'player',x:W/2,y:H/2});actors.sort((a,b)=>a.y-b.y);
for(const a of actors){if(a.x<-220||a.x>W+100||a.y<-180||a.y>H+160)continue;if(a.kind==='obstacle'){const dr=a.t.fieldMove?FieldArt.obstacle:TerrainArt.obstacle;if(fx)fx.obstacle(ctx,a.x,a.y,a.t,dr);else dr(ctx,a.x,a.y,a.t)}else if(a.kind==='legend')LegendArt.draw(ctx,a.p,a.x,a.y,time,near?.key===a.p.key,reducedMotion);else if(a.kind==='landmark')TerrainArt.landmark(ctx,a.x,a.y,a.p,F.MAPS[state.mapId].region);else if(a.kind==='building'){if(fx)fx.buildingShadow(ctx,a.x,a.y,a.b.w);BuildingArt.draw(ctx,a.b,a.x,a.y-a.b.h,time)}else if(a.kind==='fountain')WorldArt.fountain(ctx,a.x,a.y,time);else if(a.kind==='npc'){if(fx)fx.shadow(ctx,a.x,a.y,10,3,.26,2);NpcArt.draw(ctx,a.p,a.x,a.y,time,F.MAPS[state.mapId].region,reducedMotion);if(trainerAlert&&trainerAlert.person.key===a.p.key){WorldArt.alert(ctx,a.x,a.y,reducedMotion?0:trainerAlert.elapsed)}else if(a.p.key?near?.key===a.p.key:near?.kind===a.p.kind){ctx.fillStyle='#244d37';ctx.fillRect(a.x-62,a.y-62,124,16);ctx.fillStyle='#f0f0d0';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText(a.p.label,a.x,a.y-51)}}else{const moving=trainerMoving;const companion=state.field.surfing?state.team.find(c=>c.uid===state.field.surfing.uid)||active():active();if(state.field.surfing)FieldArt.surf(ctx,a.x,a.y,time);const fl=follow&&followMap===state.mapId?{x:a.x+follow.x-state.player.x,y:a.y+follow.y-state.player.y,moving:follow.moving}:{x:a.x-25,y:a.y+18,moving};const partner=()=>{if(!state.field.surfing&&fx)fx.shadow(ctx,fl.x,fl.y,11,3,.24,1);drawSprite(ctx,companion.id,fl.moving?'Walk':'Idle',state.player.dir,fl.x,fl.y,Math.min(1,50/spriteExtent(companion.id)),time)};const inFront=fl.y>a.y+4;if(!inFront)partner();trainer(a.x,a.y,state.player.dir,moving);if(inFront)partner()}}
drawTallFront(camera);for(const exit of F.worldExits(state)){const x=exit.x-camera.x,y=exit.y-camera.y;if(x>-120&&x<W+120&&y>-100&&y<H+100){if(F.MAPS[state.mapId].kind==='gym'||F.MAPS[exit.target].kind==='gym')GymArt.exit(ctx,x,y,near?.key===exit.key?exit.label:null,F.MAPS[exit.target].kind==='gym');else if(exit.frontier)WorldArt.frontier(ctx,x,y,exit.locked,near?.key===exit.key?exit.label:null);else WorldArt.exit(ctx,x,y,F.MAPS[exit.target].kind,near?.key===exit.key?exit.label:exit.beginner?'ENTRENAR · Nv. '+F.mapLevels(state,exit.target).join('–'):null,exit.beginner)}}const dark=F.fieldDark(state);if(fx)fx.ambient(ctx,W,H,camera,{dark});else{ctx.fillStyle='#17382c0b';ctx.fillRect(0,0,W,H)}if(dark)FieldArt.darkness(ctx,W,H);if(fx)fx.glow(ctx,W,H,camera,{dark});adventure.drawMinimap(ctx);const objective=F.legendObjective(state);if(objective){const o=objective.point;ctx.save();ctx.fillStyle='#173a30e8';ctx.fillRect(14,H-52,Math.min(430,W-28),32);ctx.fillStyle=objective.event.color;ctx.fillRect(14,H-52,3,32);ctx.fillStyle='#edf0d1';ctx.font='10px monospace';ctx.textAlign='left';const destination=o?(o.mapId===state.mapId?'Aquí · '+Math.floor(o.x/32)+', '+Math.floor(o.y/32):F.MAPS[o.mapId].name):objective.message;ctx.fillText('⌖ '+objective.event.title.slice(0,46),23,H-39);ctx.fillStyle='#c9d5ad';ctx.font='9px monospace';ctx.fillText(destination.slice(0,65),23,H-26);ctx.restore();}}
function drawArena(){ArenaArt.floor(ctx,battle,time);ctx.save();if(battle.shake>0)ctx.translate(Math.sin(time*100)*battle.shake,0);for(const a of battle.fighters){if(a.pending)ArenaArt.telegraph(ctx,a,a.pending,time);ArenaArt.circle(ctx,a.x,a.z,34,a===battle.fighters[0]?'#d4efb794':'#efac7b94',true)}for(const e of battle.effects)ArenaArt.effect(ctx,e);
const actors=battle.fighters.map(a=>({kind:'fighter',a,depth:C.project(a.x,a.z).depth})).concat(battle.projectiles.map(s=>({kind:'shot',s,depth:C.project(s.x,s.z).depth}))).sort((a,b)=>b.depth-a.depth);for(const actor of actors){if(actor.kind==='shot'){ArenaArt.shot(ctx,actor.s,time);continue}const a=actor.a,p=C.project(a.x,a.z,reducedMotion?0:a.y||0),scale=Math.min(6,190/spriteExtent(C.moveCreature(a).id))*p.scale;const end=battle.ending,fade=end?F.clamp(end.elapsed/end.duration,0,1):0;drawSprite(ctx,C.moveCreature(a).id,a.anim,a.dir,p.x,p.y,scale,a.animTime,end&&a.hp<=0?1-fade*.35:a.iframe>0&&Math.floor(time*16)%2?.55:1);if(a.iframe>0)ArenaArt.circle(ctx,a.x,a.z,42,'#e0f5d3');if(a.pending&&a===battle.fighters[1]){ctx.fillStyle='#f7d39d';ctx.font='bold 22px monospace';ctx.textAlign='center';ctx.fillText('!',p.x,p.y-68*p.scale)}if(a.statuses.sleep){ctx.fillStyle='#e4d5f5';ctx.font='16px monospace';ctx.textAlign='center';ctx.fillText('Z z',p.x,p.y-70*p.scale)}}for(const t of battle.texts){const p=C.project(t.x,t.z,t.y);ctx.globalAlpha=Math.min(1,t.life*2);ctx.fillStyle=t.color;ctx.font='bold 13px monospace';ctx.textAlign='center';ctx.fillText(t.text,p.x,p.y)}ctx.globalAlpha=1;ctx.restore();$('arenaMessage').classList.toggle('hidden',battle.intro<=0||!!battle.result);$('arenaMessage').textContent=['gym','trainer'].includes(battle.encounter.kind)?'¡'+F.DATA[battle.fighters[1].creature.id].name+', al combate!':'¡Aparece '+F.DATA[battle.fighters[1].creature.id].name+'!';if(battle.ending){const t=F.clamp(battle.ending.elapsed/battle.ending.duration,0,1),ease=t*t*(3-2*t);ctx.fillStyle='rgba(24,43,35,'+(ease*.10)+')';ctx.fillRect(0,0,W,H);ctx.save();ctx.globalAlpha=ease;ctx.fillStyle='#173a30d9';ctx.beginPath();ctx.roundRect(366,481,228,29,7);ctx.fill();ctx.fillStyle='#e7ead9';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText(battle.result==='caught'?'Captura completada':'Combate terminado',480,500);ctx.restore()}}
function draw(){ctx.imageSmoothingEnabled=false;if(battle)drawArena();else drawWorld()}
function loop(timestamp){const dt=Math.min((timestamp-last)/1000||0,.033);last=timestamp;time=timestamp/1000;if(ready&&!paused&&!isModal()&&!startingBattle){if(battle)updateBattle(dt);else updateWorld(dt);if(time-lastSave>6){save();lastSave=time}}draw();if(time-lastUI>3&&!battle&&ready){const el=$('companionIcon')?.querySelector('canvas');if(el){const cc=el.getContext('2d');cc.clearRect(0,0,64,64);const id=active().id,portrait=window.SpriteArt.portrait(id,0,id>151&&id!==200);if(id>151&&id!==200&&portrait){const b=portrait.bounds,anchor=portrait.anchor,zoom=64*.76/Math.max(b[2]-b[0],b[3]-b[1]);drawSprite(cc,id,'Idle',0,32-(b[0]+b[2])/2*zoom+anchor[0]*zoom,32-(b[1]+b[3])/2*zoom+anchor[1]*zoom,zoom,time)}else drawSprite(cc,id,'Idle',0,32,50,64/48,time)}lastUI=time}requestAnimationFrame(loop)}
function showGameMenu(){if(!ready||startingBattle||trainerAlert||battle?.result)return;clearInput();$('menuSummary').textContent=F.MAPS[state.mapId].name+' · '+Object.keys(state.badges).length+' / 9 medallas';$('menuPokemonCount').textContent=state.team.length+' Pokémon · '+F.DATA[active().id].name+' activo';$('mapBtn').disabled=!!battle;$('campBtn').disabled=!!battle||F.MAPS[state.mapId].kind!=='town';$('gameMenuHome').disabled=!!battle;$('menuFieldBtn').disabled=!!battle;$('menuLegendsBtn').disabled=!!battle;$('gameMenuExport').disabled=!!battle;$('gameMenuImport').disabled=!!battle;$('gameMenuSound').textContent=sound?'Desactivar sonido':'Activar sonido';fxLabel();openDialog('adventureMenu')}
$('gameMenuBtn').onclick=showGameMenu;$('gameMenuClose').onclick=()=>$('adventureMenu').close();$('gameMenuResume').onclick=()=>$('adventureMenu').close();$('menuPokemonBtn').onclick=showTeam;$('menuDexBtn').onclick=showDex;$('gameMenuHelp').onclick=showHelp;$('gameMenuHome').onclick=()=>showWelcome();$('menuFieldBtn').onclick=()=>fieldUI.open();$('gameMenuExport').onclick=exportSave;$('gameMenuImport').onclick=()=>{if(!battle){$('adventureMenu').close();$('importFile').click()}};$('gameMenuResources').onclick=showResources;$('gameMenuSound').onclick=()=>{$('soundBtn').click();$('gameMenuSound').textContent=sound?'Desactivar sonido':'Activar sonido'};function fxLabel(){const b=$('gameMenuFx');if(b)b.textContent='Efectos del mundo: '+(window.WorldFX?.enabled?'sí':'no')}$('gameMenuFx').onclick=()=>{const fx=window.WorldFX;if(!fx)return;fx.enabled=!fx.enabled;try{localStorage.setItem('frontera.fx',fx.enabled?'on':'off')}catch(e){}fxLabel()};
function renderWelcome(){
 for(const [avatar,id] of [['male','avatarMalePreview'],['female','avatarFemalePreview']]){const c=$(id),cc=c.getContext('2d');cc.clearRect(0,0,c.width,c.height);cc.save();cc.scale(2,2);TrainerArt.draw(cc,24,47,0,0,false,0,true,avatar);cc.restore();const b=$(avatar==='female'?'avatarFemaleBtn':'avatarMaleBtn');b.classList.toggle('selected',selectedAvatar===avatar);b.setAttribute('aria-pressed',String(selectedAvatar===avatar))}
 WelcomeArt.draw($('welcomeScene'),selectedAvatar);$('welcomeContinue').classList.toggle('hidden',!hasSave);$('welcomeContinue').disabled=!ready||!hasSave;$('welcomeNew').disabled=!ready;$('welcomeNew').innerHTML=(hasSave?'Nueva aventura':'Comenzar aventura')+'<span aria-hidden="true">↗</span>';$('welcomeImport').disabled=!ready;$('welcomeExport').classList.toggle('hidden',!hasSave);$('welcomeExport').disabled=!ready;
 $('welcomeSaveInfo').textContent=!ready?'Preparando tu aventura…':hasSave?'Partida guardada · '+F.MAPS[state.mapId].name+' · '+state.team.length+' Pokémon en tu equipo':'Tu aventura se guardará automáticamente en este dispositivo.';
}
function showWelcome(resetAvatar=true){if(battle||startingBattle){toast('Termina el combate antes de volver al inicio.');return}if(resetAvatar)selectedAvatar=state.avatar==='female'?'female':'male';paused=false;clearInput();if(document.body.classList.contains('fullscreen-game'))void leaveFullscreen();document.body.classList.add('at-welcome');if(resetAvatar)$('welcomeSeed').value=state.seedText;renderWelcome();setMode();openDialog('welcomeDialog')}
function enterAdventure(){document.body.classList.remove('at-welcome');$('welcomeDialog').close();canvas.focus({preventScroll:true})}
$('avatarMaleBtn').onclick=()=>{selectedAvatar='male';renderWelcome()};$('avatarFemaleBtn').onclick=()=>{selectedAvatar='female';renderWelcome()};
$('welcomeContinue').onclick=()=>{if(!ready||!hasSave)return;state.avatar=selectedAvatar;save();renderUI();enterAdventure();if(state.story.phase!=='done')showOpening()};
$('welcomeNew').onclick=()=>{if(ready)professorIntro($('welcomeSeed').value.trim()||'FRONTERA-'+Math.floor(Math.random()*100000),true)};
$('welcomeImport').onclick=()=>$('importFile').click();$('welcomeExport').onclick=exportSave;$('menuBtn').onclick=()=>showWelcome();
$('welcomeHelpBtn').onclick=()=>{const visible=$('welcomeHelp').classList.toggle('hidden')===false;$('welcomeHelpBtn').setAttribute('aria-expanded',String(visible))};
$('welcomeDialog').addEventListener('cancel',e=>e.preventDefault());
$('starterDialog').addEventListener('close',()=>{if(starterFromMenu){starterFromMenu=false;showWelcome(false)}});
function prologue(title,copy,actions){$('prologueTitle').textContent=title;$('prologueCopy').innerHTML=copy;$('prologueActions').innerHTML='';for(const [label,fn]of actions){const button=document.createElement('button');button.className='primary';button.textContent=label;button.onclick=fn;$('prologueActions').append(button)}openDialog('prologueDialog')}
function professorIntro(seed,fromMenu=false){prologue('Profesor Ciprés','<p>“¡Llegaste! Soy Ciprés. Aquí comienza tu viaje como entrenador. Los Pokémon serán tus compañeros: aprenderán contigo y necesitarán que cuides sus fuerzas.”</p><p>“Ivo también empieza hoy. Lleva toda la mañana diciendo que será el mejor de los dos… Primero, conoce a los Pokémon que preparé para ustedes.”</p>',[['Conocer a los iniciales',()=>starterDialog(seed,fromMenu)],['Volver al inicio',()=>showWelcome(false)]])}
function showOpening(){if(state.story.phase==='gift'){prologue('Tu primer equipo','<p>Ciprés: “'+F.DATA[state.team[0].id].name+' confía en ti. Te entrego 5 Poké Balls, 3 Pociones, 2 Bayas Aranja, el Mapa y una Caña Vieja. No desperdicies los objetos: los premios más valiosos son poco frecuentes.”</p><p>Ivo: “Yo elegí mi compañero pensando en ganarte. Vamos, demuestra que sabes guiar al tuyo.”</p>',[['Recibir el equipo',()=>{F.grantStarterGift(state);save();renderUI();showOpening()}]]);return}if(state.story.phase==='tutorial'){prologue('El primer duelo · Ivo','<p>Ciprés: “Yo los guío. Primero muévete, prueba una técnica, esquiva y haz una pausa para recuperar energía. Después intenten ganar el duelo. Recuperaré a ambos equipos al terminar.”</p><p>Ivo: “Hoy es una práctica. La próxima vez voy a ganarte en serio.”</p>',[['Comenzar la práctica',async()=>{F.healTeam(state);save();$('prologueDialog').close();if(!await startBattle(F.tutorialEncounter(state)))showOpening()}]]);return}const exit=F.worldExits(state).find(e=>e.beginner);prologue('Ciprés · el camino empieza aquí','<p>“Ya puedes explorar. Para entrenar comienza por '+(exit?exit.label:'la salida con el arco verde')+'. Las tiendas tienen suministros sencillos. Más adelante encontrarás tarjetas que abren nuevas plantas en el Shopping Rocío.”</p><p>Ivo: “No te quedes atrás. Nos vamos a volver a encontrar, y mi equipo también va a crecer.”</p>',[['Salir a explorar',()=>{$('prologueDialog').close();canvas.focus({preventScroll:true})}]])}
function starterArt(b,id){if(typeof Image!=='function')return;const im=new Image();im.className='starterart';im.alt=F.DATA[id].name;im.decoding='async';im.onload=()=>{const c=b.querySelector('canvas');if(c)c.remove();b.prepend(im)};im.src='assets/starters/'+id+'.png'}function renderStarters(){$('starterGrid').innerHTML='';for(const generation of Object.values(F.GENERATIONS))for(const id of generation.starters){const b=document.createElement('button');b.className='startercard';b.dataset.starter=String(id);icon(b,id,72);starterArt(b,id);const info=document.createElement('div');info.innerHTML='<b>'+F.DATA[id].name+'</b><small>'+F.DATA[id].types.map(t=>F.TYPE[t][0]).join(' · ')+'</small><small>Nv. 5 · '+F.initialMoves({id,level:5}).map(k=>F.MOVE_DATA[k].name).join(' · ')+'</small>';b.append(info);b.onclick=async()=>{b.disabled=true;if(!await loadSpecies(id,true)){b.disabled=false;toast('No se pudieron cargar los sprites. Vuelve a intentar.');return}state=F.newState(pendingSeed,id);state.avatar=selectedAvatar;hasSave=true;starterFromMenu=false;document.body.classList.remove('at-welcome');$('seedInput').value=state.seedText;battle=null;paused=false;resetCaches();save();renderUI();setMode();$('starterDialog').close();showOpening()};$('starterGrid').append(b);}}
function starterDialog(seed,fromMenu=false){starterFromMenu=fromMenu;pendingSeed=seed;renderStarters();$('starterClose').classList.toggle('hidden',!ready);openDialog('starterDialog');}
$('prologueDialog').addEventListener('cancel',e=>{e.preventDefault();if(document.body.classList.contains('at-welcome'))showWelcome(false)});

function showTeam(){if(battle?.result)return;$('teamGrid').innerHTML='';$('teamHelp').textContent=battle?(battle.awaitingSwitch?'Tu Pokémon se debilitó. Elige otro para continuar.':'Cambiar conserva vida, energía, stamina y estados. Hay '+F.trainerBonuses(state.trainer,active()).switch.toFixed(1)+' s entre cambios.'): 'Los PS se conservan entre combates. Usa medicinas en Mochila o descansa en un centro.';$('teamClose').classList.toggle('hidden',!!battle?.awaitingSwitch);
state.team.forEach((c,i)=>{const member=battle?.roster[i]||F.creatureHealth(c),selected=battle?i===battle.playerIndex:i===state.active,b=document.createElement('button');b.className='teamcard'+(selected?' active':'');b.dataset.creature=c.uid;b.disabled=member.hp<=0||!!battle&&(selected||(!battle.awaitingSwitch&&(battle.switchCooldown>0||battle.intro>0)));icon(b,c.id,64);const div=document.createElement('div');div.innerHTML=`<b>${F.DATA[c.id].name} <small>Nv. ${c.level}</small></b><small>${(member.hp<=0?'0 / '+member.maxHP+' PS · Debilitado':Math.ceil(member.hp)+' / '+member.maxHP+' PS')+(battle?' · E '+Math.round(member.energy)+' · S '+Math.round(member.stamina):' · '+escape(c.nature.name))}</small>`;b.append(div);b.onclick=async()=>{b.disabled=true;const currentBattle=battle;if(!await loadSpecies(c.id,true)){b.disabled=false;toast('No se pudo cargar el compañero. Vuelve a intentar.');return}if(battle!==currentBattle||state.team[i]!==c)return;if(battle&&!C.switchPokemon(battle,i)){toast('Espera a que el cambio esté disponible.');return}state.active=i;$('teamDialog').close();renderUI();if(battle){$('playerName').textContent=F.DATA[c.id].name;$('playerLevel').textContent='Nv. '+c.level;updateBattle(0)}save();toast(F.DATA[c.id].name+' es tu compañero activo.');canvas.focus({preventScroll:true})};$('teamGrid').append(b)});openDialog('teamDialog')}
function playEvolution(c,target){
const dlg=$('infoDialog'),host=$('infoContent'),fromId=c.id;
if(!window.EvolutionFX){if(F.evolveWithItem(state,c,target)){dlg.close();save();renderUI();toast('¡Ahora tu compañero es '+F.DATA[c.id].name+'!')}return}
const typeColor=id=>F.TYPE[F.DATA[id].types[0]]?.[1]||'#ffd86b',values=()=>{const v=F.stats(c);v[0]=F.maxHP(c);return v};
let ctl=null;
const guard=e=>{if(ctl&&ctl.cancel())e.preventDefault()};
const end=()=>{dlg.removeEventListener?.('cancel',guard);dlg.removeEventListener?.('close',onClose)};
const onClose=()=>{if(ctl)ctl.destroy();end()};
dlg.addEventListener?.('cancel',guard);dlg.addEventListener?.('close',onClose);
ctl=window.EvolutionFX.play(host,{fromId,toId:target,fromName:F.DATA[fromId].name,toName:F.DATA[target].name,colors:[typeColor(fromId),typeColor(target)],icon,tone,labels:F.STAT_NAMES,values,
commit:()=>{if(battle||active()!==c)return false;if(!F.evolveWithItem(state,c,target))return false;save();renderUI();return true},
onDone:()=>{end();if(dlg.open)dlg.close();toast('¡Ahora tu compañero es '+F.DATA[c.id].name+'!')},
onCancel:kind=>{end();if(!dlg.open)return;showEvolution();toast(kind==='fail'?'No se pudo completar la evolución.':'Evolución cancelada. No se gastó nada.')}});
const cancelBtn=host.querySelector?.('.evo-cancel');if(cancelBtn&&cancelBtn.focus)cancelBtn.focus()}
function showEvolution(){const c=active(),options=F.evolutionOptions(c);$('infoContent').innerHTML='<p class="eyebrow">EVOLUCIÓN OPCIONAL</p><h2>Elige su próximo estilo.</h2><p>Todas las etapas comparten el mismo potencial base de combate. Se conservan IV, naturaleza, entrenamiento, nivel y todos los árboles de habilidades. El nivel de evolución es aproximado: cada Pokémon tiene el suyo, cerca del indicado, y los Caramelos Raros no cuentan.</p><div id="evolutionChoices" class="teamgrid"></div>';for(const option of options){const b=document.createElement('button');b.className='teamcard';icon(b,option.target,64);const text=document.createElement('div');text.innerHTML='<b>'+F.DATA[option.target].name+'</b><small>'+F.evolutionRequirement(state,c,option.target).label+'</small>';b.append(text);b.disabled=!F.evolutionRequirement(state,c,option.target).ok;b.onclick=async()=>{if(battle||active()!==c)return;b.disabled=true;if(!await loadSpecies(option.target,true)){toast('No se pudo cargar la evolución. Vuelve a intentar.');b.disabled=false;return}if(battle||active()!==c)return;playEvolution(c,option.target)};$('evolutionChoices').append(b)}openDialog('infoDialog')}
let dexPage=0;
function renderDex(){const query=$('dexSearch').value.toLocaleLowerCase().trim().replace(/^#/,''),type=$('dexType').value,owned=new Set(state.team.map(c=>c.id));const ids=F.NATIONAL_IDS.filter(id=>(!query||F.DATA[id].name.toLocaleLowerCase().includes(query)||String(id).padStart(3,'0').includes(query))&&(!type||F.DATA[id].types.includes(type)));const pages=Math.max(1,Math.ceil(ids.length/18));dexPage=F.clamp(dexPage,0,pages-1);$('dexGrid').innerHTML='';for(const id of ids.slice(dexPage*18,dexPage*18+18)){const item=document.createElement('div');item.className='dexcard'+(owned.has(id)?' owned':'');icon(item,id,64);const text=document.createElement('div');text.innerHTML='<small>#'+String(id).padStart(3,'0')+(owned.has(id)?' · Capturado':'')+'</small><b>'+F.DATA[id].name+'</b><span>'+F.DATA[id].types.map(t=>F.TYPE[t][0]).join(' / ')+'</span><small>'+F.speciesRegions(id).map(r=>r.name).join(' · ')+'</small>';item.append(text);$('dexGrid').append(item)}if(!ids.length)$('dexGrid').innerHTML='<p class="dexempty">No hay coincidencias. Prueba otro nombre o tipo.</p>';$('dexPage').textContent=(dexPage+1)+' / '+pages+' · '+ids.length+' especies';$('dexPrev').disabled=dexPage===0;$('dexNext').disabled=dexPage===pages-1}
function showDex(){$('dexSearch').value='';$('dexType').value='';dexPage=0;renderDex();openDialog('dexDialog')}
$('dexBtn').onclick=showDex;$('dexSearch').oninput=()=>{dexPage=0;renderDex()};$('dexType').innerHTML='<option value="">Todos los tipos</option>'+Object.keys(F.HINT_POOLS).map(t=>'<option value="'+t+'">'+F.TYPE[t][0]+'</option>').join('');$('dexType').onchange=()=>{dexPage=0;renderDex()};$('dexPrev').onclick=()=>{dexPage--;renderDex()};$('dexNext').onclick=()=>{dexPage++;renderDex()};

function showHelp(){$('infoContent').innerHTML='<p class="eyebrow">GUÍA DE LA FRONTERA</p><h2>Ciudades, rutas y cuevas.</h2><p>Hay nueve regiones, de Kanto a Paldea, con 405 mapas generados por semilla y 1025 Pokémon. Ciprés te presenta a todos los iniciales juntos, entrega tus primeros objetos y guía el duelo con Ivo. Entrena por la salida de arco verde y descubre durante la aventura qué hay tras las fronteras. Las fronteras se encuentran en la ciudad inicial y también puedes usar el menú Mapa. Entra por la puerta del gimnasio. Cada interior tiene pasillos, desvíos y tres duelos previos; ganar abre el paso siguiente hasta el líder. Puedes salir a curar sin perder victorias. Las medallas de partidas anteriores conservan el acceso al líder. Acércate a un arco y pulsa Interactuar. El mapa local se revela al explorar; el atlas muestra conexiones y ciudades. Desde una posta en una ciudad puedes viajar a otras ya visitadas. Las cuevas se recorren a pie y Cuerda Huida permite salir.</p><h3>Eventos legendarios</h3><p>Menú → Leyendas abre los 94 eventos originales de Frontera, incluidos los Pokémon singulares del catálogo. Cada leyenda requiere 3, 5, 7 o 9 medallas de su propia región, dos inscripciones en rutas diferentes y una prueba en una cueva. Sigue una leyenda para ver su próximo destino y coordenadas. Las pruebas incluyen sellos en orden, ajuste de núcleos y laberintos de runas; las pistas explican cómo resolverlas. Puedes repetir una prueba sin costo. Invoca desde el santuario y captura durante el combate con 20 % de PS o menos; Master Ball funciona como siempre. Debilitarlo no permite reclutarlo después. Si huyes, pierdes, lo debilitas o recargas en combate, sal de la cueva y vuelve: las pistas, la prueba y los IV del legendario se conservan. Una captura completa el evento; los legendarios de partidas anteriores también se conservan y completan su evento. Los salvajes comunes y la pesca ya no generan legendarios.</p><h3>Rivales y gimnasios</h3><p>Ivo crece como rival en cada ciudad. En rutas y cuevas, los entrenadores te desafían automáticamente si entras en su campo de visión. Árboles, riscos y paredes bloquean su vista; puedes pasar por detrás. Aparece un aviso «!» antes del combate. Tras vencerlos, habla con ellos para pedir una revancha. Tienen equipos de uno o dos Pokémon; los líderes usan hasta tres. Al caer un Pokémon rival, el entrenador envía el siguiente. Puedes cambiar los tuyos con Q o Cambiar. Sus Pokémon no se pueden capturar. Cada ciudad tiene un gimnasio y una medalla; las nueve medallas locales completan esa región.</p><h3>Movimientos de campo</h3><p>Menú → Movimientos de campo, o H. Corte abre árboles pequeños; Fuerza empuja rocas pesadas; Golpe Roca rompe rocas agrietadas. Surf entra al agua desde la orilla y termina en tierra. Vuelo lleva a ciudades visitadas desde el exterior; Cascada sube o baja saltos de agua usando Surf. Destello ilumina cuevas; Excavar regresa a su entrada; Teletransporte vuelve al último centro donde descansaste. Las técnicas MO requieren la medalla indicada y un Pokémon compatible en tu equipo. No ocupan los cuatro espacios de combate. Los pasos abiertos y rocas movidas se guardan. Los caminos principales siguen disponibles a pie.</p><h3>Menos ruido en el mundo</h3><p>Los salvajes siguen camuflados por tipo, con menor densidad: si los tocas, el combate empieza al instante, sin confirmación ni tecla E. En rutas hay manchas de pasto largo adaptadas al bioma (pasto, helechos, follaje denso, juncos, matorral seco, hierba chamuscada, hierba de duna, matas alpinas y hierba helada): caminar por ellas puede provocar un encuentro, favorece los tipos propios de ese hábitat y los repelentes ocultan los de menor nivel. Cada ruta o cueva contiene dos Poké Balls de objetos para recoger una sola vez. El aviso muestra el icono, el nombre y la cantidad del objeto encontrado. Al regresar a una zona cambian los ejemplares salvajes; el terreno, las salidas y los objetos conservan su estado. Las familias dependen de la región, y el rango de niveles se muestra al entrar.</p><h3>Dinero y mochila</h3><p>Empiezas con ₽ 1.500, ocho Poké Balls, tres pociones, tres bayas, Mapa y Caña Vieja. Los entrenadores pagan al ganar; las revanchas pagan una fracción del primer premio. Los salvajes dan entrenamiento y experiencia. El descanso es gratuito y las tiendas venden suministros; no se rellenan Poké Balls al descansar. La reventa es menor que la compra. Los tesoros encontrados tienen valor de venta.</p><p>Los PS se conservan al ganar, capturar o escapar, y también al guardar y volver al juego. Mochila permite usar pociones y Revivir dentro y fuera de la pelea, equipar un objeto por compañero, consumir vitaminas o Caramelos Raros y mejorar la eficiencia de PP de técnicas aprendidas. Las piedras y Cordón Unión sirven para Evolucionar. Las bayas equipadas se consumen al activarse. Repelentes ocultan encuentros de menor nivel durante una distancia limitada. Pesca cerca del agua usando una caña. La bicicleta aumenta la velocidad fuera de las cuevas. Algunas funciones de los objetos se adaptan al combate de esta demo.</p><h3>Combate y controles</h3><p>WASD, flechas o mando: mover; mantén Mayús (o activa el botón Correr) para ir más rápido a pie. E: interactuar. 1, 2, 3 y 4: técnicas; 5: definitiva (una vez por Pokémon y batalla); Espacio: esquiva; Q: cambiar; C: capturar; B: curación rápida; R: intentar escapar. Antes de intentar escapar de un salvaje, baja su vida al 90 % o menos. La huida puede fallar: aléjate del rival y espera 3,5 s entre intentos. La especie rival se revela al comenzar la pelea. Selecciona Poké Ball, Super Ball o Ultra Ball junto a Capturar. Los salvajes requieren 35 % de vida o menos; Master Ball no falla. En celular puedes mover y atacar con dos dedos y usar Pantalla completa.</p><h3>Generaciones y paisajes</h3><p>La generación de tu inicial determina la región de partida: Bulbasaur comienza en Kanto y Chikorita en Johto. Hay nueve regiones, 405 mapas y las 1025 especies. Completa los nueve gimnasios de tu región para abrir la anterior y la siguiente. El atlas muestra las fronteras y permite elegir el destino. El equipo, los HP y las habilidades se conservan al viajar. Explora volcanes, montañas, desiertos, selvas y pantanos.</p><h3>Aprender movimientos</h3><p>Habilidades → Pokémon muestra todas las técnicas compatibles y el catálogo completo. Activa Disciplina, alcanza el nivel requerido y supera una prueba de memoria: observa cinco flechas y repítelas con el teclado o los botones. Aprender cuesta un punto solo al aprobar. Fallar, abandonar o recargar bloquea ese movimiento hasta subir un nivel; los demás pueden practicarse. Al nivel 100 no hay un nivel siguiente para repetir un fallo. Tu inicial comienza en nivel 5 con dos o tres movimientos, según su especie y juego de debut. Los demás se habilitan a su nivel y requieren aprobar la prueba. Las técnicas cuerpo a cuerpo incluyen una embestida corta y un arco amplio. Mientras te desplazas no regeneras energía y recuperas stamina al 50 %; al detenerte vuelve la recuperación normal. Al aprender se ocupa un espacio libre; con cuatro técnicas, elige cuál reemplazar. Las evoluciones conservan tu selección; al llegar a una forma final se desbloquea una definitiva. En Ataques puedes elegir cualquier técnica aprendida para ese quinto espacio. Su uso se conserva al cambiar de compañero y se restablece en una batalla nueva. Las especies sin evolución también tienen definitiva. Los nombres y la compatibilidad proceden del catálogo completo de datos; las mecánicas se adaptan al combate en tiempo real y las técnicas de sistemas especiales se identifican en el catálogo.</p><h3>Crecimiento libre</h3><p>Todos los Pokémon comparten 480 puntos base de combate. IV, naturaleza, EV, decisiones y habilidades dan forma al entrenamiento. Cada árbol tiene una raíz común y dos caminos excluyentes. El primer punto en una rama bloquea la otra, también para tipos y ataques. La elección se conserva al evolucionar. Si una partida anterior tenía ambas ramas, sus puntos se devuelven y eliges de nuevo; conservas la raíz, experiencia y técnicas aprendidas. Los caminos principales se exploran sin medallas; conseguirlas habilita técnicas de campo. Las tarjetas encontradas al explorar abren las plantas del Shopping Rocío; las tiendas de ciudad venden suministros básicos. Nueve medallas dan una Master Ball una sola vez.</p><h3>Teclado y pantalla completa</h3><p>En PC los mandos táctiles se ocultan. F alterna pantalla completa; K pausa; M abre el menú; E interactúa; 1–5 usa técnicas; Espacio esquiva; Q cambia compañero; C captura; V cambia la Poké Ball; B cura; R intenta escapar. En los diálogos, usa flechas para elegir, Enter o Espacio para confirmar, Tab / Mayús+Tab para recorrer campos y Esc para volver. Los botones numerados responden a 1–9. Inicio/Fin va al primer/último elemento; AvPág/RePág recorre listas largas. Las flechas y WASD siguen resolviendo la prueba de memoria; las flechas mueven la luz de los rituales.</p><h3>Tu partida</h3><p>Se conserva la colección, el entrenamiento y los árboles de las versiones anteriores. Las partidas antiguas conservan su mapa de Kanto, su equipo y sus medallas. Las nuevas fronteras aparecen al avanzar en la aventura. La Medalla Brote ya obtenida se conserva. Los fragmentos antiguos todavía permiten evoluciones compatibles, pero ya no se generan en el suelo. Exportar e Importar permiten cambiar de dispositivo.</p>';openDialog('infoDialog')}
function showResources(){$('infoContent').innerHTML='<p class="eyebrow">RECURSOS DEL PROTOTIPO</p><h2>Sprites con movimiento.</h2><p>Kanto conserva sus sprites originales. Hay 984 especies con hojas PMD, incluidas 832 incorporaciones de las generaciones 2–9, con poses y orientaciones originales. Algunas poses usan una animación alternativa disponible. Las 41 especies pendientes conservan su imagen frontal; puedes consultar <a href="assets/sprite-coverage.json" target="_blank">la cobertura por especie</a>. El escenario, el protagonista y los efectos se dibujan por código. El entrenador tiene ocho orientaciones, pasos coordinados y un parpadeo discreto. Los NPC tienen 22 diseños originales según su función, cuatro orientaciones y accesorios propios.</p><div class="resourcegrid"><div><a class="resourcelink" href="https://sprites.pmdcollab.org/" target="_blank" rel="noopener">SpriteCollab ↗</a><p>Fuente principal. Animaciones en ocho direcciones y créditos por especie.</p></div><div><a class="resourcelink" href="https://github.com/PokeAPI/sprites" target="_blank" rel="noopener">PokéAPI Sprites ↗</a><p>Sprites frontales, traseros e iconos. Útiles para fichas y menús.</p></div><div><a class="resourcelink" href="https://github.com/smogon/sprites" target="_blank" rel="noopener">Smogon / Showdown ↗</a><p>Sprites animados de combate. Referencia para ampliar el estilo.</p></div></div><h3>Créditos</h3><div class="creditsbox">Sprites originales: CHUNSOFT y contribuciones de los artistas de SpriteCollab. Créditos completos por especie en <a href="assets/credits.json" target="_blank">el registro de créditos</a>. Archivo y distribución: PMDCollab / SpriteCollab.<br>Pokémon: Nintendo / Game Freak / The Pokémon Company. Datos base, movimientos y catálogo de objetos: <a href="https://github.com/PokeAPI/pokeapi" target="_blank" rel="noopener">PokéAPI</a>. Variantes Gigamax: <a href="https://github.com/smogon/pokemon-showdown/blob/master/data/moves.ts" target="_blank" rel="noopener">Pokémon Showdown</a>.<br>Las contribuciones comunitarias de SpriteCollab se ofrecen bajo CC BY-NC 4.0: atribución y uso no comercial. Esto no concede derechos sobre la propiedad intelectual de Pokémon. <a href="assets/SPRITECOLLAB_LICENSE.md" target="_blank">Licencia del repositorio</a>.</div><h3>Qué está implementado</h3><p>9 regiones generacionales con familias propias, 8 biomas, árboles del entrenador, por tipo, por Pokémon y por técnica aprendida, mundo por semilla, individuos deterministas, exploración libre, captura, colección, entrenamiento elegido, evoluciones disponibles y arena 3D con sprites 2D contra IA. Incluye 81 ciudades, 81 gimnasios, un rival recurrente y entrenadores con equipos. Los 405 mapas, incluidos 81 interiores de gimnasio, se conectan por salidas físicas y se revelan al explorar. Hay 83 objetos oficiales con inventario, tiendas y Pokédólares. Incluye las 1025 especies de las generaciones 1 a 9. No incluye multijugador ni crianza.</p><h3>Diseño para continuar</h3><p>Los sprites PMD tienen poses laterales para una primera prueba. Los encuentros se representan con formas sutiles por tipo; los sprites completos aparecen al comenzar el combate. La especie rival se revela al iniciar la pelea. Para intentar escapar de un salvaje, primero debes quitarle al menos un 10 % de vida. La huida puede fallar; la velocidad, la distancia y los intentos previos mejoran la probabilidad. La pelea usa kits por especie, hasta cuatro técnicas y una definitiva en la última etapa, efectos de estado, energía, stamina, esquiva y cambio de Pokémon. La demo adapta las afinidades de tipo y la curva de experiencia al combate en tiempo real.</p><p><a href="descargas.html?paquete=sprites">Descargar sprites (1025 especies) ↗</a> · <a href="descargas.html?paquete=proyecto">Descargar el proyecto completo ↗</a> · <a href="diseno.md" download>Documento de diseño ↗</a></p>';openDialog('infoDialog')}
function exportSave(){if(battle){toast('Termina el combate antes de exportar.');return}const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pokemon-frontera-partida.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Partida exportada.')}
