$('importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>3000000)throw Error();const s=JSON.parse(await file.text());if(!F.validState(s))throw Error();const restored=F.upgradeState(s);if(!await loadWorldSpecies(restored))throw Error();state=restored;hasSave=true;selectedAvatar=state.avatar;battle=null;paused=false;resetCaches();$('seedInput').value=state.seedText;$('welcomeSeed').value=state.seedText;renderUI();setMode();save();if($('welcomeDialog').open)renderWelcome();toast('Partida importada.')}catch{toast('No se pudo importar: el archivo no es una partida válida.')}e.target.value=''};
const direction={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'up',w:'up',ArrowDown:'down',s:'down'},actions={'1':'m0','2':'m1','3':'m2','4':'m3','5':'m4',' ':'dash',u:'m0',i:'m1',o:'m2',p:'m3',j:'m4',l:'dash'};
window.addEventListener('keydown',e=>{shiftHeld=e.shiftKey;if(e.ctrlKey||e.metaKey||e.altKey||e.isComposing)return;if(keyboard?.handle(e))return;if(e.target.matches('input,textarea,select')||e.target.matches('button,a,summary')&&['Enter',' '].includes(e.key))return;const k=e.shiftKey&&/^Digit[1-9]$/.test(e.code||'')?e.code.slice(5):e.key.length===1?e.key.toLowerCase():e.key;if(!e.repeat&&k==='f'&&!isModal()){void toggleFullscreen();e.preventDefault();return}if(!e.repeat&&(k==='k'||k==='Pause')&&!isModal()){paused=!paused;clearInput();setMode();e.preventDefault();return}if(k==='Escape'){if(isModal())return;if(document.body.classList.contains('fullscreen-game')){void leaveFullscreen();e.preventDefault();return}paused=!paused;clearInput();setMode();e.preventDefault();return}if(!e.repeat&&k==='m'){if($('adventureMenu').open)$('adventureMenu').close();else if(!isModal())showGameMenu();e.preventDefault();return}if(isModal()||paused||startingBattle||trainerAlert)return;if(direction[k]){keys[direction[k]]=true;e.preventDefault()}if(actions[k]){e.preventDefault();if(!e.repeat)perform(actions[k])}if(!e.repeat&&k==='h'&&!battle){fieldUI.open();e.preventDefault()}if(!e.repeat&&k==='e'){interact();e.preventDefault()}if(!e.repeat&&k==='q'){showTeam();e.preventDefault()}if(!e.repeat&&k==='v'){cycleBall();e.preventDefault()}if(!e.repeat&&k==='c'){capture();e.preventDefault()}if(!e.repeat&&k==='b'){heal();e.preventDefault()}if(!e.repeat&&k==='r'){attemptFlee();e.preventDefault()}});window.addEventListener('keyup',e=>{shiftHeld=e.shiftKey;const k=e.key.length===1?e.key.toLowerCase():e.key;if(direction[k])delete keys[direction[k]]});window.addEventListener('pagehide',save);window.addEventListener('blur',()=>{shiftHeld=false;clearInput();if(battle){paused=true;setMode()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){shiftHeld=false;clearInput();save();if(battle){paused=true;setMode()}}});
document.querySelectorAll('[data-hold]').forEach(b=>{const key=b.dataset.hold;b.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||isModal()||startingBattle||trainerAlert)return;b.setPointerCapture(e.pointerId);keys[key]=true;b.classList.add('pressed')});const release=()=>{delete keys[key];b.classList.remove('pressed')};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release)});document.querySelectorAll('[data-action]').forEach(b=>{b.onclick=e=>{if(e.detail===0)perform(b.dataset.action)};b.addEventListener('pointerdown',e=>{e.preventDefault();perform(b.dataset.action)})});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',clearInput));$('starterDialog').addEventListener('cancel',e=>{if(!starterFromMenu&&!hasSave)e.preventDefault()});$('teamDialog').addEventListener('cancel',e=>{if(battle?.awaitingSwitch)e.preventDefault()});$('resultDialog').addEventListener('cancel',e=>{e.preventDefault();endBattle()});
const adventure=window.createAdventureUI({state:()=>state,battle:()=>battle,escape,save,changed:()=>{resetCaches();save();renderUI()},toast,openDialog,encounter:showEncounter,evolve:showEvolution});const legendsUI=window.createLegendsUI({state:()=>state,battle:()=>battle,locked:()=>paused||startingBattle||!!trainerAlert,escape,save,refresh:renderUI,toast,openDialog,startBattle});const fieldUI=window.createFieldUI({state:()=>state,battle:()=>battle,locked:()=>paused||startingBattle||!!trainerAlert,escape,toast,openDialog,changed:()=>{resetCaches();save();renderUI();updateWorld(0);if(state.field.surfing){const c=state.team.find(c=>c.uid===state.field.surfing.uid);if(c)void loadSpecies(c.id,true)}}});const skills=window.createSkillUI({state:()=>state,battle:()=>battle,escape,save,refresh:renderUI,toast,icon,openDialog,worldMap:adventure.map});$('bagBtn').onclick=adventure.bag;$('sidebarBagBtn').onclick=adventure.bag;$('skillsBtn').onclick=()=>skills.open();$('sidebarSkillsBtn').onclick=()=>skills.open('pokemon');$('mapBtn').onclick=()=>skills.map();
